import { IsDateString, IsEmail, IsEnum, IsNotEmpty, IsOptional, IsString, IsUUID, MaxLength } from 'class-validator';
import { PaginationQuery } from '../common/dto';

export const EMPLOYMENT_STATUSES = ['on_role', 'off_role'];

// employee_code is generated by the database (next number: 05, 06, …) and cannot be set or changed.
export const EMPLOYEE_COLUMNS = {
  fullName: 'full_name',
  email: 'email',
  designation: 'designation',
  department: 'department',
  dateOfJoining: 'date_of_joining',
};

export class CreateEmployeeDto {
  @IsString() @IsNotEmpty() @MaxLength(200) fullName;
  @IsOptional() @IsEmail() email;
  @IsOptional() @IsString() @MaxLength(100) designation;
  @IsOptional() @IsString() @MaxLength(100) department;
  @IsOptional() @IsDateString({ strict: true }) dateOfJoining;
}

export class UpdateEmployeeDto {
  @IsOptional() @IsString() @IsNotEmpty() @MaxLength(200) fullName;
  @IsOptional() @IsEmail() email;
  @IsOptional() @IsString() @MaxLength(100) designation;
  @IsOptional() @IsString() @MaxLength(100) department;
  @IsOptional() @IsDateString({ strict: true }) dateOfJoining;
}

export class UpdateStatusDto {
  @IsEnum(EMPLOYMENT_STATUSES) status;
  /** Required when removing from role; the last working day. */
  @IsOptional() @IsDateString({ strict: true }) effectiveDate;
}

export class ListEmployeesQuery extends PaginationQuery {
  @IsOptional() @IsEnum(EMPLOYMENT_STATUSES) status;
  @IsOptional() @IsString() @MaxLength(100) search;
  @IsOptional() @IsUUID() projectId;
  @IsOptional() @IsString() @MaxLength(100) department;
  @IsOptional() @IsString() @MaxLength(100) designation;
  /** Joined on or after this date. */
  @IsOptional() @IsDateString({ strict: true }) joinedFrom;
  /** Joined on or before this date. */
  @IsOptional() @IsDateString({ strict: true }) joinedTo;
}
